from typing import List

def word_wrap(text: str, width: int) -> List[str]:
    words = text.split()
    lines = []
    current = []
    current_len = 0
    for word in words:
        if not current or current_len + 1 + len(word) <= width:
            current.append(word)
            current_len += 1 + len(word)
        else:
            lines.append(' '.join(current))
            current = [word]
            current_len = len(word)
    if current:
        lines.append(' '.join(current))
    return lines

def truncate(text: str, limit: int, suffix: str = '...') -> str:
    if len(text) <= limit:
        return text
    cut = limit - len(suffix) + 1
    if cut < 0:
        cut = 0
    return text[:cut] + suffix

SMALL_WORDS = {'a', 'an', 'and', 'the', 'of', 'in', 'on', 'or', 'to', 'at', 'by', 'for'}

def title_case(text: str) -> str:
    words = text.split()
    result = []
    for i, word in enumerate(words):
        lower = word.lower()
        if i == 0 or lower not in SMALL_WORDS:
            result.append(lower.capitalize())
        else:
            result.append(lower)
    return ' '.join(result)

def dedupe_spaces(text: str) -> str:
    return ' '.join(text.split())

